for (const uppgift of window.BANK) {
  if (FACIT_NEWTON_V2_DEL1[uppgift.id]) {
    uppgift.t = uppgift.t.replace(/<\/?strong>/g, "");
    uppgift.s = FACIT_NEWTON_V2_DEL1[uppgift.id];
  }
}

